  "evaluations": [
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:BGD:17068",
      "iso3": "BGD",
      "ruler_id": "2992",
      "ruler_year_id": 17068,
      "ruler_name": "Sheikh Hasina",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "5B",
      "rubric_version": "chapter_5b_v3",
      "calibration_batch_id": "chapter-judge:2022-top20-hybrid-v2-judges-v1:2022:5B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:RUS:15706",
        "dossier:2022-top20-hybrid-v2:2022:DEU:16984",
        "dossier:2022-top20-hybrid-v2:2022:VNM:19647"
      ],
      "score_1_to_10": 6.5,
      "insufficient_evidence_reason": null,
      "confidence_score": 0.78,
      "plausible_score_range": {
        "lower": 6.0,
        "upper": 7.0
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E0055",
          "explanation": "Fast pandemic support showed the authorities using fiscal capacity for broad relief rather than pure extraction."
        },
        {
          "evidence_id": "E0058",
          "explanation": "The IMF program agreement signaled an active stabilization response to 2022 macro strain."
        },
        {
          "evidence_id": "E0067",
          "explanation": "The central-bank governor appointment shows direct executive action on monetary management."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E0064",
          "explanation": "Fuel-price hikes, high inflation, and reserve pressure show serious household stress and weak stabilization."
        },
        {
          "evidence_id": "E0068",
          "explanation": "Late-2022 macro indicators show inflation, balance-of-payments stress, and a multiple exchange-rate regime."
        },
        {
          "evidence_id": "E0056",
          "explanation": "IMF criticism of banking regulation and tax reform shows structural weaknesses that were not solved."
        }
      ],
      "inherited_baseline_and_constraints": "Bangladesh entered 2022 with strong long-run growth and poverty reduction, but also with inflation pressure, reserve strain, weak banking quality, and pandemic-era fiscal demands.",
      "ruler_attribution": "Attribution is reasonably strong for crisis response, fiscal design, and key economic appointments, but weaker for household-level execution and structural banking reform.",
      "supported_lenses": [
        "5B.1",
        "5B.3",
        "5B.6",
        "5B.8",
        "5B.9",
        "5B.10"
      ],
      "missing_or_weak_lenses": [
        "5B.2",
        "5B.4",
        "5B.5",
        "5B.7"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E0064",
          "explanation": "The economy was still under inflation and reserve pressure."
        },
        {
          "evidence_id": "E0068",
          "explanation": "Macro vulnerabilities deepened despite the policy response."
        },
        {
          "evidence_id": "E0056",
          "explanation": "Structural banking and revenue weaknesses remained unresolved."
        }
      ],
      "source_mix": "Mostly IMF and World Bank surveillance, plus Reuters and domestic budget/appointment reporting; no structured local priors were collected in this experiment.",
      "structured_prior_summary": "Structured local priors were unavailable across all lenses, so the judgment rests on the embedded dossier evidence, the lens coverage map, and source-confidence metadata only.",
      "chapter_rationale": "Hasina receives a 6.5 because the record shows real, ruler-attributed efforts to protect livelihoods and stabilize the economy, not just rhetoric. The strongest positives are the large pandemic support package, the IMF-backed stabilization program, social safety-net spending, and the central-bank leadership change; the main negatives are still-serious inflation, reserve pressure, and unresolved banking and trade bottlenecks. The evidence supports competence and some broad social protection, but not a materially higher score because the economy remained fragile and several weaknesses were structural rather than corrected.",
      "lower_anchor_rejected": "A score near 5 would understate the amount of active fiscal and social-protection response visible in 2022.",
      "higher_anchor_rejected": "A score near 7.5 would overstate durability, because the dossier still shows clear inflation, reserve, and banking stress.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
      "chapter_specific": [
        {
          "field": "trajectory",
          "value": "Modestly upward from the pandemic baseline, but the path was fragile and heavily constrained by inflation, reserves, and banking weakness."
        },
        {
          "field": "external_conditions",
          "value": "Pandemic carryover, global inflation, import-price pressure, and financial-sector stress materially limited what the government could achieve."
        },
        {
          "field": "distribution_and_household_effects",
          "value": "Safety nets and transfers were real positives, but household welfare remained pressured by prices and weaker execution than the announcement record suggests."
        }
      ]
    },
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:BRA:19646",
      "iso3": "BRA",
      "ruler_id": "3413",
      "ruler_year_id": 19646,
      "ruler_name": "Jair Bolsonaro",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "5B",
      "rubric_version": "chapter_5b_v3",
      "calibration_batch_id": "chapter-judge:2022-top20-hybrid-v2-judges-v1:2022:5B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:RUS:15706",
        "dossier:2022-top20-hybrid-v2:2022:DEU:16984",
        "dossier:2022-top20-hybrid-v2:2022:VNM:19647"
      ],
      "score_1_to_10": 4.5,
      "insufficient_evidence_reason": null,
      "confidence_score": 0.71,
      "plausible_score_range": {
        "lower": 4.0,
        "upper": 5.0
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E0066",
          "explanation": "The 2022 primary surplus suggests fiscal outcomes were not uniformly poor."
        },
        {
          "evidence_id": "E0064",
          "explanation": "Investment and contracted-project activity show some state-capacity and infrastructure follow-through."
        },
        {
          "evidence_id": "E0048",
          "explanation": "GDP growth remained positive in 2022 despite the difficult environment."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E0051",
          "explanation": "Food insecurity and food-price pressure were severe and broadly felt."
        },
        {
          "evidence_id": "E0057",
          "explanation": "Election-year spending that bypassed the cap raised fiscal and inflation concerns."
        },
        {
          "evidence_id": "E0050",
          "explanation": "Inflation stayed elevated and household purchasing power remained under strain."
        }
      ],
      "inherited_baseline_and_constraints": "Brazil entered 2022 with post-pandemic recovery, inflation shocks, and labor-market weakness; global commodity and food-price swings mattered a lot, but so did election-year fiscal choices.",
      "ruler_attribution": "Attribution is mixed: some positive growth and fiscal outcomes reflect the broader recovery and institutional settings, while the most salient negative choices were clearly linked to Bolsonaro's political strategy.",
      "supported_lenses": [
        "5B.3",
        "5B.4",
        "5B.6",
        "5B.8",
        "5B.9",
        "5B.10"
      ],
      "missing_or_weak_lenses": [
        "5B.1",
        "5B.2",
        "5B.5",
        "5B.7"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E0048",
          "explanation": "Positive GDP growth kept the score from dropping further."
        },
        {
          "evidence_id": "E0066",
          "explanation": "A primary surplus and completed projects provide some counterweight."
        }
      ],
      "source_mix": "Official statistics, central-bank minutes, World Bank analysis, Reuters reporting, and government program releases; no structured local priors were collected in this experiment.",
      "structured_prior_summary": "Structured local priors were unavailable across all lenses, so the judge relied on the embedded dossier evidence and the source-confidence framing only.",
      "chapter_rationale": "Bolsonaro lands at 4.5 because the year mixed real macro activity with clearly harmful short-term politics and weak household outcomes. Growth, employment, investment, and even a fiscal surplus show that the economy was not collapsing, but food insecurity, inflation, and election-year spending that strained fiscal credibility kept the chapter firmly below the competence threshold. The evidence supports a mixed record with some competent outcomes, yet not enough fairness, durability, or restraint to justify a higher score.",
      "lower_anchor_rejected": "A score near 3 would ignore the positive growth, surplus, and investment evidence.",
      "higher_anchor_rejected": "A score near 6 would overstate the policy quality because food insecurity, inflation, and fiscal loosening were serious and ruler-linked.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
      "chapter_specific": [
        {
          "field": "trajectory",
          "value": "Mixed and uneven: output and employment improved, but inflation, food insecurity, and election-year fiscal loosening eroded the prosperity story."
        },
        {
          "field": "external_conditions",
          "value": "Commodity and food-price shocks mattered, but the administration amplified them through discretionary spending and weak structural reform."
        },
        {
          "field": "distribution_and_household_effects",
          "value": "Household welfare lagged headline growth; the food-insecurity evidence is the clearest sign that gains were not broadly shared."
        }
      ]
    },
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:CHN:15832",
      "iso3": "CHN",
      "ruler_id": "1432",
      "ruler_year_id": 15832,
      "ruler_name": "Xi Jinping",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "5B",
      "rubric_version": "chapter_5b_v3",
      "calibration_batch_id": "chapter-judge:2022-top20-hybrid-v2-judges-v1:2022:5B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:RUS:15706",
        "dossier:2022-top20-hybrid-v2:2022:DEU:16984",
        "dossier:2022-top20-hybrid-v2:2022:VNM:19647"
      ],
      "score_1_to_10": 6.0,
      "insufficient_evidence_reason": null,
      "confidence_score": 0.74,
      "plausible_score_range": {
        "lower": 5.5,
        "upper": 6.5
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E0072",
          "explanation": "Fixed-asset investment still grew, with infrastructure and manufacturing relatively strong."
        },
        {
          "evidence_id": "E0075",
          "explanation": "The labor market created millions of new urban jobs in 2022."
        },
        {
          "evidence_id": "E0076",
          "explanation": "The central bank used a broad stabilization toolkit to support growth and the property sector."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E0073",
          "explanation": "Property development collapsed sharply, showing a major drag on prosperity."
        },
        {
          "evidence_id": "E0066",
          "explanation": "Developer investment and new construction starts fell hard, indicating deep sector stress."
        },
        {
          "evidence_id": "E0075",
          "explanation": "Youth unemployment remained very high even with aggregate job creation."
        }
      ],
      "inherited_baseline_and_constraints": "China entered 2022 with strong state capacity and a large investment apparatus, but also with a property bubble, weak private investment, and rising youth-labor-market strain.",
      "ruler_attribution": "Attribution is strong for the overall policy environment and party-state direction, but weaker for whether Xi personally optimized the growth mix rather than simply presiding over it.",
      "supported_lenses": [
        "5B.1",
        "5B.2",
        "5B.3",
        "5B.4",
        "5B.6",
        "5B.8",
        "5B.9",
        "5B.10"
      ],
      "missing_or_weak_lenses": [
        "5B.5",
        "5B.7"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E0073",
          "explanation": "The property sector contracted sharply."
        },
        {
          "evidence_id": "E0066",
          "explanation": "Private investment and new starts were too weak to call the year broadly balanced."
        }
      ],
      "source_mix": "Official party-state texts and statistics, NBS and PBC data, plus Reuters-based reporting on the property crisis and personnel consolidation; no structured local priors were collected in this experiment.",
      "structured_prior_summary": "Structured local priors were unavailable across all lenses; the judge used the dossier's own evidence and the projection's lens mapping only.",
      "chapter_rationale": "Xi scores 6.0 because the record shows a powerful state apparatus that still delivered investment growth, job creation, and aggressive stabilization. The score is capped well below the top band because the property crash, weak private investment, and youth unemployment reveal a serious distortion in the prosperity model, while the evidence on correction and broad fairness is weaker than the evidence on top-down control. This is a competent but constrained performance, not a transformational one.",
      "lower_anchor_rejected": "A score near 5 would underrate the scale of state-led investment, jobs, and stabilization capacity.",
      "higher_anchor_rejected": "A score near 7 would overstate breadth and durability, because the property crisis and weak private sector remained unresolved.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
      "chapter_specific": [
        {
          "field": "trajectory",
          "value": "Growth held up, but the economy became more state-led and less balanced as the property sector weakened and private investment lagged."
        },
        {
          "field": "external_conditions",
          "value": "The property downturn, pandemic after-effects, and global slowdown constrained the year; policy response mattered, but so did structural imbalances."
        },
        {
          "field": "distribution_and_household_effects",
          "value": "Aggregate investment and jobs improved, yet youth labor distress and property weakness meant household gains were uneven."
        }
      ]
    },
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:COD:16113",
      "iso3": "COD",
      "ruler_id": "2830",
      "ruler_year_id": 16113,
      "ruler_name": "F\u0000e9lix Tshisekedi",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "5B",
      "rubric_version": "chapter_5b_v3",
      "calibration_batch_id": "chapter-judge:2022-top20-hybrid-v2-judges-v1:2022:5B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:RUS:15706",
        "dossier:2022-top20-hybrid-v2:2022:DEU:16984",
        "dossier:2022-top20-hybrid-v2:2022:VNM:19647"
      ],
      "score_1_to_10": 4.0,
      "insufficient_evidence_reason": null,
      "confidence_score": 0.68,
      "plausible_score_range": {
        "lower": 3.5,
        "upper": 4.5
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E0069",
          "explanation": "World Bank budget support and reform financing show some credible governance and connectivity agenda."
        },
        {
          "evidence_id": "E0072",
          "explanation": "Telecom liberalization and market reforms point to real policy effort."
        },
        {
          "evidence_id": "E0075",
          "explanation": "The 145-territories program shows direct presidential sponsorship of local development works."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E0078",
          "explanation": "The missing mining-company payments indicate serious state-capture and leakage problems."
        },
        {
          "evidence_id": "E0071",
          "explanation": "Poverty reduction remained elusive despite growth."
        },
        {
          "evidence_id": "E0074",
          "explanation": "Eastern conflict remained severe, limiting any broad prosperity claim."
        }
      ],
      "inherited_baseline_and_constraints": "The DRC entered 2022 with conflict, weak state capacity, mining dependence, poverty, and major delivery gaps. Those constraints were severe, but they do not erase the need to judge what the presidency did with the room it had.",
      "ruler_attribution": "Attribution is partial: Tshisekedi clearly sponsored reform and development programs, but the strongest positive items are often external financing or self-reported program design, while the negative leakages and conflict were only partly under his direct control.",
      "supported_lenses": [
        "5B.3",
        "5B.4",
        "5B.6",
        "5B.8",
        "5B.9",
        "5B.10"
      ],
      "missing_or_weak_lenses": [
        "5B.1",
        "5B.2",
        "5B.5",
        "5B.7"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E0078",
          "explanation": "The audit finding on missing funds is a major negative signal."
        },
        {
          "evidence_id": "E0071",
          "explanation": "Broad poverty gains were still not visible."
        }
      ],
      "source_mix": "IMF and World Bank surveillance, presidential-office program announcements, and Reuters-based audit reporting; no structured local priors were collected in this experiment.",
      "structured_prior_summary": "Structured local priors were unavailable across all lenses; the judgment relies on the dossier evidence and lens mapping only.",
      "chapter_rationale": "Tshisekedi receives 4.0 because the dossier shows real reform activity and some development ambition, but not enough durable prosperity to move the country out of the mixed band. The strongest negatives are the missing mining payments, continued conflict, and the fact that poverty reduction remained elusive even where macro indicators improved. That combination supports some credit for policy effort, but not a high score for actual household prosperity.",
      "lower_anchor_rejected": "A score near 3 would understate the range of active reform and development initiatives shown in the record.",
      "higher_anchor_rejected": "A score near 5 would overstate results, because leakage, conflict, and poverty persistence still dominate the household picture.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
      "chapter_specific": [
        {
          "field": "trajectory",
          "value": "There was reform motion, but the prosperity trajectory remained weak because state capacity and conflict constraints outweighed the announced programs."
        },
        {
          "field": "external_conditions",
          "value": "Conflict in the east, mining dependence, and inherited fragility constrained what could be achieved in 2022."
        },
        {
          "field": "distribution_and_household_effects",
          "value": "Household gains were thin; poverty and conflict costs were still too large to describe the year as broadly prosperous."
        }
      ]
    },
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:DEU:16984",
      "iso3": "DEU",
      "ruler_id": "2975",
      "ruler_year_id": 16984,
      "ruler_name": "Olaf Scholz",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "5B",
      "rubric_version": "chapter_5b_v3",
      "calibration_batch_id": "chapter-judge:2022-top20-hybrid-v2-judges-v1:2022:5B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:RUS:15706",
        "dossier:2022-top20-hybrid-v2:2022:TUR:15972",
        "dossier:2022-top20-hybrid-v2:2022:VNM:19647"
      ],
      "score_1_to_10": 7.0,
      "insufficient_evidence_reason": null,
      "confidence_score": 0.77,
      "plausible_score_range": {
        "lower": 6.5,
        "upper": 7.5
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E0048",
          "explanation": "The supplementary budget was an aggressive, coherent crisis response with direct household relief."
        },
        {
          "evidence_id": "E0051",
          "explanation": "The 200 billion euro shield shows large-scale stabilization and protection of firms and households."
        },
        {
          "evidence_id": "E0052",
          "explanation": "The OECD judged the government had acted swiftly and in a generally well-targeted way."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E0059",
          "explanation": "The Bundesrechnungshof warned the energy-shield financing design carried significant fiscal and constitutional risk."
        },
        {
          "evidence_id": "E0053",
          "explanation": "The IMF still expected weak growth and recommended tighter fiscal policy."
        },
        {
          "evidence_id": "E0057",
          "explanation": "Employment was strong, but inflation and real-income pressure were still present in the same year."
        }
      ],
      "inherited_baseline_and_constraints": "Germany faced the energy shock from Russia's war, high inflation, and the need to cushion households and firms without undermining fiscal credibility.",
      "ruler_attribution": "Attribution is strong for the crisis packages and cabinet coordination, but weaker for the independent labor-market and employment tailwinds that also supported the year.",
      "supported_lenses": [
        "5B.1",
        "5B.3",
        "5B.4",
        "5B.6",
        "5B.8",
        "5B.9",
        "5B.10"
      ],
      "missing_or_weak_lenses": [
        "5B.2",
        "5B.5",
        "5B.7"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E0059",
          "explanation": "Independent auditors questioned the financing design."
        },
        {
          "evidence_id": "E0053",
          "explanation": "The IMF still saw room for tighter policy and weaker growth."
        }
      ],
      "source_mix": "Federal ministry releases, constitutional text, labor statistics, OECD/IMF surveillance, and the federal audit office; no structured local priors were collected in this experiment.",
      "structured_prior_summary": "Structured local priors were unavailable across all lenses; the judgment relies on embedded evidence and coverage mapping only.",
      "chapter_rationale": "Scholz scores 7.0 because the government responded to the 2022 energy shock with unusually large, concrete relief and stabilization measures that protected households and firms. The main reason the score is not higher is that the financing design drew serious fiscal and constitutional criticism and inflation still eroded purchasing power, even if the labor market stayed exceptionally strong. The dossier therefore supports effective crisis management with real but bounded weaknesses.",
      "lower_anchor_rejected": "A score near 6 would understate the scale and coherence of the energy-crisis response.",
      "higher_anchor_rejected": "A score near 8 would overstate durability, because fiscal-design criticism and inflation remain material.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
      "chapter_specific": [
        {
          "field": "trajectory",
          "value": "The year was a defensive success: Germany preserved employment and cushioned the shock, but the upside was limited by inflation and fiscal stress."
        },
        {
          "field": "external_conditions",
          "value": "Russia's war in Ukraine and the energy-price shock were the dominant constraints; policy quality mattered because the shock was external and severe."
        },
        {
          "field": "distribution_and_household_effects",
          "value": "Relief was broad and household-focused, but the benefits were partly temporary and still offset by inflation."
        }
      ]
    },
